        let datum = BasedRootDatum::from_simple_data(
            2,
            vec![vec![2]],
            vec![Weight::new(vec![2, 0])],
            vec![Coweight::new(vec![1, 0])],
        )
        .unwrap();
        let inner_class = compact_inner(datum.clone(), 2);
        let value = element(
            &inner_class,
            vec![rational(-1, 2), rational(9, 2)],
            WeylGroup::new(datum).identity().unwrap(),
